$(() => {
  const host = window.parent;
  const config = {"rosterFromWorldbook": true, "roles": {"蕾拉妮": {"folder": "蕾拉妮", "fallback": "data:image/png;base64,"}, "艾琳": {"folder": "艾琳", "fallback": "data:image/png;base64,"}}};
  host.__rpgSceneConfig = config;
  host.dispatchEvent(new Event('rpg-scene-config-changed'));
  $(window).on('pagehide', () => {
    if (host.__rpgSceneConfig === config) {
      delete host.__rpgSceneConfig;
      host.dispatchEvent(new Event('rpg-scene-config-changed'));
    }
  });
});